package com.example.auth

import java.security.MessageDigest
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

/**
 * Session management service with CSRF protection.
 * Uses double-submit cookie pattern with HMAC-based tokens.
 */
class SessionManager(
    private val tokenSecret: ByteArray,
    private val sessionStore: ConcurrentHashMap<String, SessionData> = ConcurrentHashMap()
) {
    data class SessionData(
        val userId: String,
        val roles: Set<String>,
        val createdAt: Instant,
        val csrfToken: String,
        val lastActivity: Instant
    )

    data class RequestContext(
        val sessionId: String?,
        val csrfCookie: String?,
        val csrfHeader: String?,
        val requestPath: String,
        val requestMethod: String,
        val requestBody: Map<String, Any>?
    )

    data class AuthResult(
        val authenticated: Boolean,
        val userId: String? = null,
        val roles: Set<String> = emptySet(),
        val reason: String = ""
    )

    companion object {
        private val SAFE_METHODS = setOf("GET", "HEAD", "OPTIONS")
        private val SESSION_TIMEOUT_SECONDS = 3600L
        private val PUBLIC_PATHS = setOf("/health", "/login", "/public")
    }

    fun createSession(userId: String, roles: Set<String>): Pair<String, String> {
        val sessionId = generateSecureId()
        val csrfToken = generateCsrfToken(sessionId)
        val session = SessionData(
            userId = userId,
            roles = roles,
            createdAt = Instant.now(),
            csrfToken = csrfToken,
            lastActivity = Instant.now()
        )
        sessionStore[sessionId] = session
        return Pair(sessionId, csrfToken)
    }

    fun authenticateRequest(ctx: RequestContext): AuthResult {
        // Public paths don't require authentication
        if (isPublicPath(ctx.requestPath)) {
            return AuthResult(authenticated = true, reason = "public_path")
        }

        // Validate session exists
        val sessionId = ctx.sessionId
            ?: return AuthResult(authenticated = false, reason = "no_session")

        val session = sessionStore[sessionId]
            ?: return AuthResult(authenticated = false, reason = "invalid_session")

        // Check session expiry
        if (isSessionExpired(session)) {
            sessionStore.remove(sessionId)
            return AuthResult(authenticated = false, reason = "session_expired")
        }

        // CSRF validation for state-changing methods
        if (!isSafeMethod(ctx.requestMethod)) {
            if (!validateCsrf(ctx, session)) {
                return AuthResult(authenticated = false, reason = "csrf_validation_failed")
            }
        }

        // Update last activity
        sessionStore[sessionId] = session.copy(lastActivity = Instant.now())

        return AuthResult(
            authenticated = true,
            userId = session.userId,
            roles = session.roles
        )
    }

    private fun validateCsrf(ctx: RequestContext, session: SessionData): Boolean {
        val cookieToken = ctx.csrfCookie ?: return false
        val headerToken = ctx.csrfHeader ?: return false

        // Both tokens must be present and non-empty
        if (cookieToken.isBlank() || headerToken.isBlank()) return false

        // Verify cookie token matches session token
        val cookieValid = MessageDigest.isEqual(
            cookieToken.toByteArray(),
            session.csrfToken.toByteArray()
        )

        // Verify header token matches cookie token
        val headerMatchesCookie = MessageDigest.isEqual(
            headerToken.toByteArray(),
            cookieToken.toByteArray()
        )

        // Both must be valid
        return cookieValid && headerMatchesCookie
    }

    private fun isPublicPath(path: String): Boolean {
        val normalizedPath = normalizePath(path)
        return PUBLIC_PATHS.any { normalizedPath.startsWith(it) }
    }

    private fun normalizePath(path: String): String {
        // Decode percent-encoded characters for comparison
        val decoded = percentDecode(path)
        // Collapse multiple slashes and resolve relative segments
        val segments = decoded.split("/").filter { it.isNotEmpty() && it != "." }
        val resolved = mutableListOf<String>()
        for (segment in segments) {
            if (segment == "..") {
                if (resolved.isNotEmpty()) resolved.removeAt(resolved.size - 1)
            } else {
                resolved.add(segment)
            }
        }
        return "/" + resolved.joinToString("/")
    }

    private fun percentDecode(input: String): String {
        val result = StringBuilder()
        var i = 0
        while (i < input.length) {
            if (input[i] == '%' && i + 2 < input.length) {
                val hex = input.substring(i + 1, i + 3)
                try {
                    result.append(hex.toInt(16).toChar())
                    i += 3
                } catch (e: NumberFormatException) {
                    result.append(input[i])
                    i++
                }
            } else {
                result.append(input[i])
                i++
            }
        }
        return result.toString()
    }

    private fun isSafeMethod(method: String): Boolean {
        return method.uppercase() in SAFE_METHODS
    }

    private fun isSessionExpired(session: SessionData): Boolean {
        return Instant.now().epochSecond - session.lastActivity.epochSecond > SESSION_TIMEOUT_SECONDS
    }

    private fun generateSecureId(): String {
        val bytes = ByteArray(32)
        java.security.SecureRandom().nextBytes(bytes)
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
    }

    private fun generateCsrfToken(sessionId: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(tokenSecret, "HmacSHA256"))
        mac.update(sessionId.toByteArray())
        mac.update(Instant.now().toEpochMilli().toString().toByteArray())
        return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal())
    }
}
